import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column whitelist - but sortDir is not validated
        String[] allowedCols = {"created_at", "amount", "department", "status"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equals(sortCol)) { validSort = true; break; }
            }
            if (!validSort) sortCol = "created_at";
        } else {
            sortCol = "created_at";
        }
        if (sortDir == null) sortDir = "ASC";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String sql = buildQuery(reportType, startDate, endDate, department, sortCol, sortDir);
            log.info("Executing report query: " + sql);

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(sql)) {
                JSONArray results = new JSONArray();
                ResultSetMetaData meta = rs.getMetaData();
                while (rs.next()) {
                    JSONObject row = new JSONObject();
                    for (int i = 1; i <= meta.getColumnCount(); i++) {
                        row.put(meta.getColumnName(i), rs.getObject(i));
                    }
                    results.put(row);
                }
                resp.setContentType("application/json");
                resp.getWriter().write(results.toString());
            }
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String buildQuery(String reportType, String startDate, String endDate,
                              String department, String sortCol, String sortDir) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT id, created_at, amount, department, status, description ");
        sb.append("FROM expense_reports WHERE created_at BETWEEN '");
        sb.append(startDate).append("' AND '").append(endDate).append("'");

        if ("pending".equals(reportType)) {
            sb.append(" AND status = 'PENDING'");
        } else if ("approved".equals(reportType)) {
            sb.append(" AND status = 'APPROVED'");
        }

        if (department != null && !department.isEmpty()) {
            sb.append(" AND department = '").append(department).append("'");
        }

        sb.append(" ORDER BY ").append(sortCol).append(" ").append(sortDir);
        sb.append(" LIMIT 500");
        return sb.toString();
    }

    private boolean validateSession(String token) {
        // Validates against session store
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT 1 FROM sessions WHERE token = ? AND expires_at > NOW()")) {
            ps.setString(1, token);
            return ps.executeQuery().next();
        } catch (SQLException e) {
            return false;
        }
    }
}
